using System;
using System.Collections;
using System.Collections.Generic;
using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "ThunderingRiposteEffect", menuName = "Data/Battle/Effects/Austra/ThunderingRiposte Effect")]
public class ThunderingRiposteEffect : Effect
{
	[Header("Thundering Riposte Effects")]
	[SerializeField]
	private PurifiedLightningAction purifiedLightningAction;

	[SerializeField]
	private CurrentCorruptedAnimals currentCorruptedAnimals;

	[SerializeField]
	private Vector2 lightningStartPosition = new Vector2(4.5f, 6f);

	[Header("Description")]
	[SerializeField]
	private PurifyAction purifyAction;

	[NonSerialized]
	private int timesAmount;

	[NonSerialized]
	private GameObject constantVFXGameObjectDuringThunderingRiposte;

	public override string GetEffectDescription(int amount, GameObject effectOwner = null)
	{
		if (amount == EffectsValues.NO_VALUE)
		{
			amount = -1;
		}
		return Smart.Format(base.localizationManager.GetLocalizedWheneverYouDodgeCorruption(), Smart.Format(base.localizationManager.GetLocalizedForEach(), purifyAction.GetActionDescription(amount).RemoveLast(), GetLocalizedDescription())) + AppendedDescription();
	}

	protected override string AppendedDescription()
	{
		return "\n" + ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedThisPurifyCanTriggerCritical();
	}

	public override void Initialize(int effectAmount, GameObject effectOwner, GameObject source)
	{
		timesAmount = 0;
	}

	public int ActivateThunderingRiposte(int effectAmount, GameObject effectOwner, int corruptionDodgedAmount)
	{
		if (timesAmount == 0)
		{
			ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueAction(ThunderingRiposteActivation(effectAmount, effectOwner, corruptionDodgedAmount));
			ReferenceSingleton<GameStateManager>.Instance.SetState(ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState);
		}
		timesAmount++;
		return effectAmount;
	}

	private IEnumerator ThunderingRiposteActivation(int purifyAmount, GameObject effectOwner, int corruptionDodgedAmount)
	{
		yield return new WaitForSeconds(0.1f);
		List<GameObject> targets = currentCorruptedAnimals.activeCorruptedAnimals;
		if (targets.Count > 0)
		{
			PlayerEffects playerEffects = effectOwner.GetComponent<PlayerEffects>();
			playerEffects.IsEffectActive(this, activateFeedback: true, enqueueFeedback: false);
			if (IsThirdVFXEnabled())
			{
				constantVFXGameObjectDuringThunderingRiposte = GetThirdVFX();
				constantVFXGameObjectDuringThunderingRiposte.GetComponent<ParticleEmissionController>().SetActive(value: true);
			}
			yield return new WaitForSeconds(0.5f);
			for (int i = 0; i < timesAmount; i++)
			{
				if (targets.Count <= 0)
				{
					continue;
				}
				effectOwner.GetComponent<PlayerSpriteControl>().PlayAnimationForced(AnimationType.Attack, AnimationChangeType.ReturnToIdleAnimation);
				int amount = playerEffects.IsPlayerCriticalCheckCritical(purifyAmount * corruptionDodgedAmount, fierceSquall: false, sentPur: false);
				for (int j = 0; j < targets.Count; j++)
				{
					targets[j].GetComponent<CorruptionStats>().Purify(amount, null);
					if (IsSecondVFXEnabled())
					{
						if (IsSecondVFXEnabled())
						{
							PlayEffectActivationSFX();
						}
						GetSecondVFX(GetVFXOwnerPosition(targets[j]), 3f).transform.GetChild(0).GetChild(0).position = lightningStartPosition;
					}
				}
				purifiedLightningAction.PurifyAction.PlaySFX();
				if (i < timesAmount - 1)
				{
					yield return new WaitForSeconds(purifiedLightningAction.DelayBetweenCorruptPurify);
				}
			}
		}
		timesAmount = 0;
		if (constantVFXGameObjectDuringThunderingRiposte != null)
		{
			constantVFXGameObjectDuringThunderingRiposte.GetComponent<ParticleEmissionController>().SetActive(value: false);
			ReferenceSingleton<PoolHandler>.Instance.StoreObject(constantVFXGameObjectDuringThunderingRiposte, 5f);
		}
	}
}
